"use client"

import * as React from "react"
import { OTPField as OTPFieldPrimitive } from "@base-ui/react/otp-field"
import { cva } from "class-variance-authority"

import { cn } from "@/lib/utils"

import "@/styles/otp-field.styles.css"

type OTPFieldSize = "sm" | "default" | "lg"

export interface OTPFieldProps extends Omit<
  OTPFieldPrimitive.Root.Props,
  "className" | "autoSubmit" | "onValueChange"
> {
  className?: string
  size?: OTPFieldSize
  autoSubmit?: boolean
  onValueChange?: OTPFieldPrimitive.Root.Props["onValueChange"]
}

export interface OTPFieldInputProps extends Omit<
  OTPFieldPrimitive.Input.Props,
  "className" | "size"
> {
  className?: string
  size?: OTPFieldSize
}

export interface OTPFieldSeparatorProps extends Omit<
  OTPFieldPrimitive.Separator.Props,
  "className"
> {
  className?: string
  size?: OTPFieldSize
}

const OTPFieldSizeContext = React.createContext<OTPFieldSize>("default")

const otpFieldRootVariants = cva("cn-otp-field")

const otpFieldInputVariants = cva("cn-otp-input", {
  variants: {
    size: {
      sm: "cn-otp-sm",
      default: "cn-otp-default",
      lg: "cn-otp-lg",
    },
  },
  defaultVariants: {
    size: "default",
  },
})

const otpFieldSeparatorVariants = cva("cn-otp-separator", {
  variants: {
    size: {
      sm: "cn-otp-separator-sm",
      default: "cn-otp-separator-default",
      lg: "cn-otp-separator-lg",
    },
  },
  defaultVariants: {
    size: "default",
  },
})

export function OTPField({
  className,
  size = "default",
  autoSubmit = false,
  onValueChange,
  length,
  value,
  ...props
}: OTPFieldProps): React.ReactElement {
  const rootRef = React.useRef<React.ElementRef<typeof OTPFieldPrimitive.Root>>(null)
  const lastValueRef = React.useRef(typeof value === "string" ? value : "")
  const submitFrameRef = React.useRef<number | null>(null)
  const submitQueuedRef = React.useRef(false)

  React.useEffect(() => {
    if (typeof value === "string") {
      lastValueRef.current = value
    }
  }, [value])

  React.useEffect(() => {
    return () => {
      if (submitFrameRef.current !== null) {
        cancelAnimationFrame(submitFrameRef.current)
      }
    }
  }, [])

  const handleValueChange = React.useCallback<NonNullable<OTPFieldProps["onValueChange"]>>(
    (nextValue, eventDetails) => {
      onValueChange?.(nextValue, eventDetails)

      const targetLength = typeof length === "number" ? length : 0
      if (!autoSubmit || targetLength < 1) {
        lastValueRef.current = nextValue
        return
      }

      const wasComplete = lastValueRef.current.length >= targetLength
      const isComplete = nextValue.length >= targetLength

      if (!isComplete) {
        submitQueuedRef.current = false
      }

      if (!wasComplete && isComplete && !submitQueuedRef.current) {
        submitQueuedRef.current = true

        queueMicrotask(() => {
          submitFrameRef.current = requestAnimationFrame(() => {
            submitFrameRef.current = null
            submitQueuedRef.current = false

            const form = rootRef.current?.closest("form")
            if (form instanceof HTMLFormElement) {
              form.requestSubmit()
            }
          })
        })
      }

      lastValueRef.current = nextValue
    },
    [autoSubmit, length, onValueChange]
  )

  return (
    <OTPFieldSizeContext.Provider value={size}>
      <OTPFieldPrimitive.Root
        ref={rootRef}
        className={cn(otpFieldRootVariants(), className)}
        data-size={size}
        data-slot="otp-field"
        autoSubmit={false}
        length={length}
        onValueChange={handleValueChange}
        value={value}
        {...props}
      />
    </OTPFieldSizeContext.Provider>
  )
}

export function OTPFieldInput({
  className,
  size,
  ...props
}: OTPFieldInputProps): React.ReactElement {
  const inheritedSize = React.useContext(OTPFieldSizeContext)

  return (
    <OTPFieldPrimitive.Input
      className={cn(otpFieldInputVariants({ size: size ?? inheritedSize }), className)}
      data-slot="otp-field-input"
      {...props}
    />
  )
}

export function OTPFieldSeparator({
  className,
  size,
  ...props
}: OTPFieldSeparatorProps): React.ReactElement {
  const inheritedSize = React.useContext(OTPFieldSizeContext)

  return (
    <OTPFieldPrimitive.Separator
      className={cn(otpFieldSeparatorVariants({ size: size ?? inheritedSize }), className)}
      data-slot="otp-field-separator"
      {...props}
    />
  )
}

export { OTPFieldPrimitive }

@layer components {
  .cn-otp-field {
    display: flex;
    align-items: center;
    gap: calc(8 * var(--cn-unit));
    width: 100%;
    min-width: 0;
  }
  .cn-otp-input {
    --otp-width: 40;
    --otp-height: 44;
    --otp-type: 18;
    box-sizing: border-box;
    flex-shrink: 0;
    width: calc(var(--otp-width) * var(--cn-unit));
    height: calc(var(--otp-height) * var(--cn-unit));
    margin: 0;
    padding: 0;
    border: 1px solid var(--cn-border-control);
    border-radius: var(--cn-radius-control);
    background: var(--cn-surface);
    color: var(--cn-text);
    text-align: center;
    font-family: var(--font-mono, ui-monospace, monospace);
    font-size: calc(var(--otp-type) * var(--cn-unit));
    line-height: 1;
    font-weight: 600;
    text-transform: uppercase;
    transition:
      border-color var(--cn-duration-fast) var(--cn-ease-standard),
      background-color var(--cn-duration-fast) var(--cn-ease-standard);
  }
  .cn-otp-sm {
    --otp-width: 36;
    --otp-height: 40;
    --otp-type: 16;
  }
  .cn-otp-lg {
    --otp-width: 44;
    --otp-height: 48;
    --otp-type: 20;
  }
  .cn-otp-input::placeholder {
    color: var(--cn-text-muted);
    opacity: 1;
  }
  .cn-otp-input[data-filled] {
    background: var(--cn-surface-selected);
  }
  .cn-otp-input:is(:read-only, [data-readonly]) {
    background: var(--cn-surface-muted);
  }
  .cn-otp-input:is([data-invalid], [aria-invalid="true"]) {
    border-color: var(--cn-status-destructive-border);
  }
  .cn-otp-input:is(:disabled, [data-disabled]) {
    background: var(--cn-surface-disabled);
    border-color: var(--cn-border-disabled);
    color: var(--cn-text-disabled);
    cursor: not-allowed;
  }
  .cn-otp-input:focus-visible {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-otp-separator {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    color: var(--cn-text-muted);
    width: calc(16 * var(--cn-unit));
    font-size: calc(14 * var(--cn-unit));
  }
  .cn-otp-separator-sm {
    width: calc(12 * var(--cn-unit));
    font-size: calc(12 * var(--cn-unit));
  }
  .cn-otp-separator-lg {
    width: calc(20 * var(--cn-unit));
    font-size: calc(16 * var(--cn-unit));
  }
  /* Explicit consumer opt-in: six full-size slots in two rows, preserving DOM/keyboard order. */
  .cn-otp-wrap {
    display: grid;
    grid-template-columns: repeat(3, max-content);
    width: fit-content;
  }
}
@media (hover: hover) {
  @layer components {
    .cn-otp-input:not(
        :disabled,
        [data-disabled],
        [data-readonly],
        [data-invalid],
        [aria-invalid="true"]
      ):hover {
      border-color: var(--cn-border-hover);
    }
  }
}
@media (prefers-reduced-motion: reduce) {
  .cn-otp-input {
    transition: none;
  }
}
@media (forced-colors: active) {
  .cn-otp-input:focus-visible {
    outline-color: Highlight;
  }
}
@layer components {
  .cn-otp-container {
    container-type: inline-size;
    width: 100%;
    min-width: 0;
    padding: calc(4 * var(--cn-unit));
  }
  .cn-otp-responsive {
    width: fit-content;
    margin-inline: auto;
  }
}
@container (max-width: 23rem) {
  @layer components {
    .cn-otp-responsive {
      display: grid;
      grid-template-columns: repeat(3, max-content);
    }
    .cn-otp-responsive:has(> div) {
      grid-template-columns: max-content;
    }
    .cn-otp-responsive > .cn-otp-separator {
      justify-self: center;
    }
  }
}
